import assert from 'node:assert/strict';
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';
const root = 'D:/idea-projects/AutoJs6-Plugin-Bun-Runtime';
const task = 'E:/.codex-tmp/watch-reload-fix-20260913';
const helpers = join(root, 'tools/bun-runtime/experimental/api28/app-probe/probe-common.mjs');
const { json, fileFacts, validateReceipt, validateProbes, verifyProbeApk,
  parseInstrumentation, validateReport } = await import(pathToFileURL(helpers));
const directory = join(task, 'probe-sony28');
const record = json(join(directory, 'probe-result.json'));
const build = validateReceipt(record.build);
assert.deepEqual(build, json(join(task, 'probe-apks/probe-build.json')));
const probes = validateProbes(json(join(root, 'tools/bun-runtime/experimental/api28/app-probe/probes.json')));
for (const apk of build.apks) verifyProbeApk(join(task, 'probe-apks', apk.filename), apk, build.runtimes, build.supervisor);
assert.equal(record.passed, false);
assert.equal(record.distributionReady, false);
assert.equal(record.runs.length, 2);
assert.equal(record.runs[0].passed, false);
assert.equal(record.runs[1].passed, true);
assert.equal(record.lifecycle.installedUid, 10769);
assert.equal(record.lifecycle.uninstalled, true);
assert.equal(record.lifecycle.finalUidProcessCount, 0);
assert.deepEqual(record.lifecycle.rounds, [1, 2].map(round => ({ round, packageProcessAbsent: true, uidProcessCount: 0 })));
const instrumentation = [1, 2].map((round, index) => {
  const filename = `instrumentation-${round}.txt`, path = join(directory, filename);
  const text = readFileSync(path, 'utf8');
  assert(Buffer.byteLength(text) < 1024 * 1024);
  assert.doesNotMatch(text, /INSTRUMENTATION_FAILED|Process crashed/);
  if (index === 0) {
    const lines = text.split(/\r?\n/);
    assert.deepEqual(lines.filter(line => line.startsWith('INSTRUMENTATION_CODE:')), ['INSTRUMENTATION_CODE: 0']);
    const reports = lines.filter(line => line.startsWith('INSTRUMENTATION_RESULT: report='));
    assert.equal(reports.length, 1);
    assert.deepEqual(JSON.parse(reports[0].slice('INSTRUMENTATION_RESULT: report='.length)), record.runs[index]);
  } else assert.deepEqual(parseInstrumentation(text), record.runs[index]);
  return { filename, ...fileFacts(path), text };
});
for (const run of record.runs) {
  assert.deepEqual(run.probes.map(p => p.id), probes.map(p => p.id));
  assert.equal(run.environment.uid, 10769);
  assert.equal(run.environment.apiLevel, 28);
  assert.equal(run.environment.model, 'G8441');
  const accepted = run.probes.filter(p => p.passed);
  // Validate a derived subset of individual successful observations, never
  // modify the retained failed report or treat this projection as a suite pass.
  validateReport({ ...run, probes: accepted, passed: accepted.every(p => p.passed) }, {
    abi: 'arm64-v8a', api: 28, pageSize: 4096,
    apk: build.apks.find(a => a.abi === 'arm64-v8a'), runtime: build.runtimes['arm64-v8a'],
    supervisor: build.supervisor.artifacts.find(a => a.abi === 'arm64-v8a'), variant: build.variant,
    probes: probes.filter(p => accepted.some(a => a.id === p.id)),
  });
}
const failed = record.runs.flatMap(r => r.probes).filter(p => !p.passed);
assert.equal(failed.length, 1);
const failure = failed[0];
assert.equal(failure.id, 'watch-reload-trap');
assert.equal(failure.exitCode, 1);
assert.equal(failure.processReaped, true);
assert.equal(failure.workspaceRemoved, true);
assert.equal(failure.elapsedMillis, 590);
const proof = JSON.parse(failure.stdout.trim().slice('WATCH_RELOAD_RESULT='.length));
assert(failure.stdout.startsWith('WATCH_RELOAD_RESULT='));
assert.deepEqual(proof, failure.watchReloadEvidence);
assert.equal(proof.passed, false);
assert.equal(proof.pid, 9280);
assert.equal(proof.childPid, 9283);
assert.equal(proof.error, 'Error: expected actual watch generation 2');
assert.deepEqual(proof.cleanup, { signal: 'SIGABRT', gone: true, timedOut: false, overflow: false, bytes: 486 });
assert.deepEqual(proof.rows.map(r => r.generation), [0, 1]);
for (const row of proof.rows) {
  assert.equal(row.pid, 9283); assert.equal(row.uid, 10769);
  assert.deepEqual(row.inherited, [-1, false, -1]);
  assert.deepEqual(row.state, [0, 0]); assert.deepEqual(row.prepared, [0, 1]);
  assert.deepEqual(row.delivery, [1, 9283]);
  for (const field of ['rawClose', 'marker', 'afterRemoval']) assert.deepEqual(row[field], [-1, 38]);
  assert.deepEqual(row.stdio, proof.rows[0].stdio);
}
const log = readFileSync(join(task, 'owned-pid9283.log'), 'utf8');
assert.match(log, /09-13 22:12:47\.972\s+9283\s+9283 W libc\s+: pthread_create failed: clone failed: Try again/);
assert.equal(readFileSync(join(task, 'crash-buffer-owned.log'), 'utf8'), '');
const observer = json(join(task, 'probe-sony28-observed.json'));
assert.equal(observer.actualRunnerExitCode, 1); assert.equal(observer.observerError, null);
assert.equal(observer.postflight.length, 1);
assert.equal(observer.postflight[0].uid, 10769);
assert.equal(observer.postflight[0].uidIndependentlyObserved, true);
assert.deepEqual(observer.postflight[0].remainingPackageLines, []);
assert.deepEqual(observer.postflight[0].remainingUidProcessLines, []);
const driver = json(join(task, 'probe-sony28.driver.json'));
assert.equal(driver.exitCode, 1);
const archive = {
  schemaVersion: 1, kind: 'archived-watch-reload-abort-failure', archivedAt: new Date().toISOString(),
  projectBaseCommit: 'bf5cb72529172b628475f1307d0d08606330b778',
  passed: false, countedInAcceptance: false, distributionReady: false, pluginBinderExercised: false,
  productionReleaseAcceptance: false, officialMinimumApi: 33,
  scope: 'Initial thirteen-patch API 28 attempt: one watched child aborted after two emitted images; preserve the entire 69/70 attempt outside accepted suite counts. No descriptor leak was observed in the emitted images. The unchanged repeat round passed, but does not erase the first-round failure.',
  summary: { environments: 1, rounds: 2, probesPerRound: 35, totalProbes: 70, passedProbes: 69, failedProbes: 1 },
  sourceBinding: 'Current receipt, all fixed definitions, both APKs, runtime bytes and original raw instrumentation are checked. Successful individual observations are semantically validated as a derived subset; the original full report remains false and unchanged.',
  inputs: build.inputs, probes, build,
  diagnosis: {
    ownedUid: 10769, parentPid: 9280, watchedPid: 9283, observedSignal: 'SIGABRT',
    precedingOwnedProcessMessage: 'pthread_create failed: clone failed: Try again',
    threadCreationError: 'EAGAIN', matchingCrashStackAvailable: false,
    conclusion: 'Owned-process logcat establishes a failed clone immediately before the observed abort. Without a crash stack or in-failure resource snapshot, the exact abort call chain and reason for EAGAIN remain unconfirmed. Later memory/thread snapshots are not contemporaneous proof. This is not attributed to the historical ART/ADB-JDWP crash.',
    retryBasis: 'Retained owned-PID diagnostic plus the already-passing second round justified one identical-APK retry with no source, fixture, budget or device configuration change. This finite retry does not close watch reload stability or resource-pressure coverage.',
    ownedLogcat: { ...fileFacts(join(task, 'owned-pid9283.log')), text: log },
    emptyOwnedCrashBuffer: fileFacts(join(task, 'crash-buffer-owned.log')),
    captureReceipt: { ...fileFacts(join(task, 'sony28-crash-capture.json')),
      capturedAt: json(join(task, 'sony28-crash-capture.json')).capturedAt,
      records: json(join(task, 'sony28-crash-capture.json')).records.map(({ command, ...item }) =>
        ({ ...item, command: ['adb.exe', ...command.slice(1)] })) },
  },
  driver: { exitCode: driver.exitCode, startedAt: driver.startedAt, finishedAt: driver.finishedAt,
    binding: fileFacts(join(task, 'probe-sony28.driver.json')), log: fileFacts(join(task, 'probe-sony28.log')) },
  independentUidCleanup: observer,
  archiver: { filename: 'archive-abort-failure.mjs', ...fileFacts(new URL(import.meta.url)), text: readFileSync(new URL(import.meta.url), 'utf8') },
  reports: [{ ...Object.fromEntries(Object.entries(record).filter(([key]) => key !== 'build')),
    rawReport: fileFacts(join(directory, 'probe-result.json')), instrumentation }],
};
writeFileSync(join(root, 'docs/compatibility/2026-09-13-m3-watch-reload-api28-abort-failure.json'), JSON.stringify(archive, null, 2) + '\n', { flag: 'wx' });
console.log(JSON.stringify(archive.summary));
